"""Original bedside reasoning: probability, test interpretation and measurement quality."""
from qbank_authoring import question,ref
rows=[]
LR=ref('Clinical Methods: sensitivity, specificity and predictive value','https://www.ncbi.nlm.nih.gov/books/NBK383/')
BP=ref('AHA scientific statement on human BP measurement','https://pmc.ncbi.nlm.nih.gov/articles/PMC11409525/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A disease has a pretest probability of 20%. A positive finding has LR+ 5. What is the approximate post-test probability?', '56%',[
 ('25%','This confuses the pretest odds with the updated probability.'),('50%','The exact odds conversion gives a result slightly above one-half.'),('100%','Multiplying probability directly by the likelihood ratio is incorrect.')],
 'Convert probability to odds before applying a likelihood ratio','**Pretest odds are 0.20/0.80 = 0.25.**',['Multiplying by five gives post-test odds of one-point-two-five.','Probability is 1.25/2.25, approximately fifty-six percent.'],'**Use the result to decide whether more evidence or treatment is needed.**',['A positive finding does not necessarily establish disease.','The decision threshold depends on consequences and alternatives.'],[['Pretest odds','0.25'],['After LR+ 5','1.25'],['Probability','About 56%']],[LR])

q('Pretest probability is 50% and a negative test has LR− 0.1. What is the approximate remaining disease probability?', '9%',[
 ('1%','This underestimates the post-test probability.'),('10% exactly by direct subtraction','The correct method uses odds, producing about nine-point-one percent.'),('40%','Subtracting the LR from probability is not valid.')],
 'A strong negative result can still leave residual risk','**Pretest odds of one become post-test odds of zero-point-one.**',['Zero-point-one divided by one-point-one is about nine percent.','Whether this is low enough depends on the disease and decision.'],'**Do not equate a negative test with zero probability.**',['Consider test quality and applicability.','Use further assessment if the remaining risk is clinically unacceptable.'],[['Pretest','50%'],['Post-test odds','0.1'],['Probability','About 9.1%']],[LR])

q('A study includes 100 people with disease and 100 without. A sign is positive in 90 with disease and 20 without. What is its positive predictive value in this study?', 'About 82%',[
 ('90%','This is sensitivity, not the proportion of positive results that are true positives.'),('80%','This is specificity in the stated data.'),('50%','This is the study prevalence.')],
 'Identify the denominator asked by the question','**PPV is true positives divided by all positives.**',['Here ninety divided by one hundred ten is about eighty-two percent.','Predictive value changes with disease prevalence and selection.'],'**Do not transport a study PPV uncritically to another setting.**',['Use a relevant pretest probability and likelihood information.','Assess verification and spectrum biases.'],[['True positives','90'],['All positives','110'],['PPV','81.8%']],[LR])

q('Two examination signs arise from the same underlying mechanism and are strongly correlated. Which probability approach is most defensible?', 'Avoid simply multiplying their likelihood ratios as though they were independent',[
 ('Multiply both LRs without checking dependence','This can double-count the same information.'),('Ignore every physical sign because correlation exists','Correlated information can still be useful when modeled appropriately.'),('Add the LRs directly to the pretest probability','This is not a valid probability update.')],
 'More findings do not always mean proportionally more evidence','**Conditional dependence can exaggerate combined diagnostic certainty.**',['A validated multivariable rule can account for relationships better than naive multiplication.','Clinical judgment should recognize shared mechanisms.'],'**Use independently informative findings and validated combinations.**',['Check whether the model fits the patient population.','Keep uncertainty explicit.'],[['Independent evidence','Can support sequential update'],['Dependent evidence','Risk of double-counting'],['Alternative','Validated combined model']],[LR])

q('A highly sensitive screening test is negative in a patient with very high clinical suspicion. Which statement is correct?', 'The result lowers probability but may not reduce it enough to exclude disease safely',[
 ('High sensitivity guarantees every negative is true','False negatives can occur.'),('The pretest probability becomes irrelevant after testing','Post-test probability depends on both prior probability and test performance.'),('Specificity alone determines the meaning of this negative result','Negative-result interpretation requires the appropriate likelihood information.')],
 'Rule-out shortcuts depend on the starting risk','**Even a favorable LR− may leave important residual disease probability.**',['Timing, sampling and spectrum can reduce actual performance.','A test can be sensitive in one setting and less so in another.'],'**Reassess the diagnostic pathway when suspicion and result conflict.**',['Consider repeat or alternative testing when appropriate.','Do not repeat tests without a clear question.'],[['Prior risk','Still matters'],['Negative result','Reduces, not abolishes risk'],['Decision','Depends on residual risk']],[LR])

q('A bedside sign performs well in advanced hospitalized disease but poorly in mild outpatient disease. Which concept best explains the difference?', 'Spectrum effects related to disease severity and comparator population',[
 ('Sensitivity and specificity are immutable constants in every setting','They can change with spectrum, technique and thresholds.'),('Prevalence alone must alter every sensitivity value mathematically','Prevalence affects predictive values directly; spectrum and selection can change sensitivity.'),('The sign must therefore have been fabricated','Different populations can produce legitimate performance differences.')],
 'Diagnostic performance belongs to a population and method','**Severity, alternative diagnoses and selection influence accuracy.**',['A dramatic classic sign may be absent early.','Study setting and examiner expertise affect transportability.'],'**Apply evidence that resembles the patient and examination conditions.**',['Avoid treating textbook sensitivity as universal.','Use uncertainty ranges where available.'],[['Advanced spectrum','More obvious signs'],['Mild spectrum','More subtle disease'],['Application','Population match']],[LR])

q('In an accuracy study, only patients with a positive bedside sign receive the reference test. Which bias is a concern?', 'Partial verification bias',[
 ('Randomization removes all bias automatically','There is no such protection in the described selective verification.'),('Lead-time bias as the primary mechanism','That concerns apparent survival timing in screening rather than selective diagnostic confirmation.'),('Publication bias is the only possible concern','Selective verification directly distorts the accuracy estimate.')],
 'The reference standard must be applied appropriately','**Missed disease among unverified negative patients can bias accuracy estimates.**',['Differential reference standards can create another verification problem.','Blinding and complete follow-up also matter.'],'**Check study methods before adopting a test claim.**',['Ask what happened to negative and indeterminate results.','Prefer appropriate independent reference assessment.'],[['Problem','Only positives verified'],['Bias','Partial verification'],['Review','Negative/indeterminate follow-up']],[LR])

q('Two clinicians disagree frequently about whether a subtle sign is present. Which distinction is most relevant?', 'Reliability is agreement/reproducibility, whereas validity is whether the sign identifies the intended state',[
 ('A valid sign must always have perfect interobserver agreement','Accuracy and reproducibility are related but distinct.'),('High agreement proves the sign diagnoses disease correctly','Observers can consistently agree on an uninformative sign.'),('A single confident observer removes the need for standardization','Technique and training remain important.')],
 'A useful examination needs both reproducibility and meaning','**Agreement does not itself establish diagnostic accuracy.**',['Prevalence and scoring rules influence agreement statistics.','Training and clear operational definitions can improve consistency.'],'**Standardize technique and verify uncertain high-stakes findings.**',['Use appropriate imaging or objective measurement when necessary.','Document equivocal signs honestly.'],[['Reliability','Reproducibility'],['Validity','Accuracy/meaning'],['Improvement','Standard technique and training']],[LR])

q('A standard cuff is used on a substantially larger arm than its labeled range. What bias is expected?', 'Blood pressure can be overestimated because the cuff is too small',[
 ('A predictable large underestimation','Undercuffing generally biases readings upward.'),('No effect because all cuffs are equivalent','Cuff dimensions relative to the arm matter.'),('The error can be corrected by subtracting a universal fixed number','The size of the error varies.')],
 'Measurement error can create a false diagnosis','**Use an appropriate validated cuff for the measured arm circumference.**',['Position, rest, support and device validity also affect readings.','Do not rely on an arbitrary correction factor.'],'**Repeat with correct technique before acting on a questionable value.**',['Assess urgent symptoms separately when present.','Use repeated and out-of-office readings as appropriate.'],[['Too small','Often reads high'],['Selection','Arm circumference/range'],['Action','Correct and repeat']],[BP],style='clinical_scenario')

q('During seated BP measurement, the supported cuffed arm is held well below heart level. What error is expected?', 'A hydrostatic contribution that can falsely elevate the measured pressure',[
 ('A falsely low pressure from the lower position','Below-heart positioning adds rather than subtracts a hydrostatic component.'),('No effect if the cuff is automatic','Position affects automated as well as manual measurement.'),('The result directly measures central aortic pressure without positional effects','A brachial cuff reading is not such a direct measurement.')],
 'Reference height matters','**The cuff should be positioned at the appropriate heart level.**',['Unsupported muscle effort can add another source of error.','Back, feet and rest conditions also matter.'],'**Standardize position and repeat the measurement.**',['Document special positioning when standard conditions are impossible.','Interpret small changes cautiously if technique changes.'],[['Arm below heart','Potential upward bias'],['Support','Avoid isometric effort'],['Repeat','Standardized position']],[BP],style='clinical_scenario')
